/* @lc app=leetcode id=2503 lang=kotlin */ class Solution { fun maxPoints(grid: Array<IntArray>, queries: IntArray): IntArray = queries.indices.sortedBy { queries[it] }.let { sIdx -> IntArray(queries.size).also { res -> java.util.PriorityQueue<IntArray>(compareBy { it[0] }).also { pq -> pq.add(intArrayOf(grid[0][0], 0, 0)).let { Array(grid.size) { BooleanArray(grid[0].size) }.also { vis -> 0.also { vis[0][0] = true }.let { sIdx.fold(0) { count, idx -> (count + generateSequence { if (pq.isNotEmpty() && pq.peek()[0] < queries[idx]) pq.poll() else null }.sumOf { curr -> 1.also { arrayOf(0 to 1, 0 to -1, 1 to 0, -1 to 0).forEach { (dr, dc) -> (curr[1] + dr to curr[2] + dc).let { (r, c) -> if (r in grid.indices && c in grid[0].indices && !vis[r][c]) true.also { vis[r][c] = it }.also { pq.add(intArrayOf(grid[r][c], r, c)) } } } } }).also { res[idx] = it } } } } } } } } }